        'data-typewriter': typewriterOn ? '1' : '0',
        'data-immersive': immersive ? '1' : '0',
        // R10: the 灵感便签 column floats over the same right edge as the dock,
        // so applyDockLane() widens the reserved lane while it is mounted. The
